void loop()
{
    unsigned long now = millis();

    // handlePhysicalButton(now);

    // handleTouchscreen(now);

    // gameEngine.update(now);

    if (now - lastRenderTime >= renderIntervalMs)
    {
        lastRenderTime = now;
        // displayUI.update(now);

        drawHome();
    }

    int currentState = digitalRead(BUTTON_PIN);

    // Reset timer if the pin state changed (noise or transition)
    if (currentState != lastFlickerState)
    {
        lastDebounceTime = millis();
        lastFlickerState = currentState;
    }

    // Check if the reading has remained stable longer than the debounce delay
    if ((millis() - lastDebounceTime) > DEBOUNCE_DELAY_MS)
    {
        if (lastSteadyState == HIGH && currentState == LOW)
        {
            // Trigger action on transition from unpressed to pressed
            Serial.println("Button Clicked!");

            tone(BUZZER_PIN, NOTE_F4, 20);
        }
        lastSteadyState = currentState;
    }
}
